insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-08','en-c1-08',null,5,8,'published',1,'{"id":"en-c1-08","baseId":"en-c1-08","revision":1,"level":"C1","levelIndex":5,"order":8,"title":"Participle clauses: sabab va ehtiyotkor talqin","objective":"Qisqartirilgan sababiy aloqani egasi va dalili bilan tekshirasiz.","context":"Participle clauses: sabab va ehtiyotkor talqin","prerequisites":["en-c1-07"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin.","Ega asosiy gap bilan mos; passive uchun past participle.","Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring."],"pattern":"Having reviewed … / Concerned about … / Assuming that …","examples":["Having reviewed the evidence, we revised the claim.","Concerned about access, the committee requested a trial.","Assuming that attendance remains stable, the plan is feasible.","Written for specialists, the report needs explanation.","Not having compared groups, we cannot identify the cause.","Working with limited data, the team stated its uncertainty."],"vocabulary":[{"id":"en-c1-08-v0","term":"premise","meaning":"asosiy faraz","ipa":"/ˈpremɪs/","collocation":"test a premise","example":"It tests the subject, the time relation, and any premise compressed into the clause."},{"id":"en-c1-08-v1","term":"implicit","meaning":"yashirin","ipa":"/ɪmˈplɪsɪt/","collocation":"an implicit assumption","example":"an implicit assumption"},{"id":"en-c1-08-v2","term":"feasibility","meaning":"amalga oshish imkoniyati","ipa":"/ˌfiːzəˈbɪləti/","collocation":"assess feasibility","example":"assess feasibility"},{"id":"en-c1-08-v3","term":"qualify","meaning":"cheklab ifodalamoq","ipa":"/ˈkwɒlɪfaɪ/","collocation":"qualify a claim","example":"qualify a claim"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["Having reviewed … / Concerned about … / Assuming that …","Having reviewed the evidence, we revised the claim.","Concerned about access, the committee requested a trial."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The recommendation depends on an assumption.","Lower attendance would change cost per participant.","Preserve the premise in the concise summary."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Written for specialists, the report needs explanation.","audio":"/english-course/v7.23/en-c1-08-dictation.mp3"},"exercises":[{"id":"en-c1-08-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Having ___ the evidence, we revised it. (review)","answers":["reviewed"],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …","options":["reviewed","reviewing","review"]},{"id":"en-c1-08-gap","type":"grammarFill","skill":"grammar","prompt":"Having ___ the evidence, we revised it. (review)","answers":["reviewed"],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …"},{"id":"en-c1-08-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Having reviewed the evidence, we revised the claim."],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …","tokens":["Having","reviewed","the","evidence,","we","revised","the","claim."]},{"id":"en-c1-08-fix","type":"correction","skill":"grammar","prompt":"Having reviewed the evidence, the claim was revised.","answers":["Having reviewed the evidence, the team revised the claim."],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …"},{"id":"en-c1-08-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["asosiy faraz","yashirin","amalga oshish imkoniyati","cheklab ifodalamoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Having reviewed … / Concerned about … / Assuming that …","left":["premise","implicit","feasibility","qualify"],"options":["asosiy faraz","yashirin","amalga oshish imkoniyati","cheklab ifodalamoq"]},{"id":"en-c1-08-transform","type":"transformation","skill":"grammar","prompt":"Avvalgi amal bilan: We reviewed the evidence, then revised the claim.","answers":["Having reviewed the evidence, we revised the claim."],"hint":"Having reviewed … / Concerned about … / Assuming that …","explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin."},{"id":"en-c1-08-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The recommendation depends on an assumption.","Lower attendance would change cost per participant.","Preserve the premise in the concise summary."],"answers":["The recommendation depends on an assumption.\nLower attendance would change cost per participant.\nPreserve the premise in the concise summary."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-08-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["Having reviewed the evidence, we revised the claim."],"tokens":["Having","reviewed","the","evidence,","we","revised","the","claim."],"hint":"Having reviewed … / Concerned about … / Assuming that …","explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin."},{"id":"en-c1-08-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Conditional inversion va ehtiyot chorasi: Til vositasini tanlang: ___ we known, we would have revised it.","answers":["Had"],"explanation":"Had we known = if we had known; were it not for = if it were not for. Should you need … kelajak ehtimoli uchun rasmiy shart. Inverted clause yordamchini oldinga oladi, not egadan keyin; vaqt ma’nosi saqlansin.","hint":"Had we known / Were it not for / Should you need","options":["Had","Have","Were"],"recap":true,"sourceLesson":"Conditional inversion va ehtiyot chorasi"},{"id":"en-c1-08-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Hedging va epistemic modality: Til vositasini tanlang: The findings may ___ a trend. (suggest)","answers":["suggest"],"explanation":"May suggest, appears consistent with, is likely to turli ehtimol va dalil aloqalarini bildiradi. Must xulosa kuchi; must majburiyat ham bo‘lishi mumkin — kontekstni tekshiring. Hedging noaniqlikni yashirmasin: aynan nima noma’lum va nima aniq ekanini ayting.","hint":"may suggest / appears consistent with / cannot establish","options":["suggest","suggests","suggested"],"recap":true,"sourceLesson":"Hedging va epistemic modality"},{"id":"en-c1-08-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Murakkab reporting va passive: Til vositasini tanlang: The policy is believed to have been ___. (revise)","answers":["revised"],"explanation":"Is believed to have been changed oldingi passive hodisaga ishora qiladi. It has been suggested that … taklif, established fact emas. Bir manbani ko‘p sayt takrorlashi mustaqil tasdiq bo‘lmaydi.","hint":"is believed to have been / has been suggested that","options":["revised","revising","revise"],"recap":true,"sourceLesson":"Murakkab reporting va passive"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A proposal says, “Assuming that attendance remains stable, the plan is feasible.” The assumption is essential: if attendance falls, the cost per participant may rise. A shortened clause makes that condition compact, but readers must not lose it when quoting the recommendation. Another sentence says, “Having reviewed the evidence, the claim was revised.” Its implied subject is the claim, which cannot review evidence. The writer names the team and checks whether the review actually preceded the revision. Editing therefore involves more than selecting an elegant participle. It tests the subject, the time relation, and any premise compressed into the clause. These checks prevent concise prose from quietly strengthening a conclusion.","sentences":["A proposal says, “Assuming that attendance remains stable, the plan is feasible.","” The assumption is essential: if attendance falls, the cost per participant may rise.","A shortened clause makes that condition compact, but readers must not lose it when quoting the recommendation.","Another sentence says, “Having reviewed the evidence, the claim was revised.","” Its implied subject is the claim, which cannot review evidence.","The writer names the team and checks whether the review actually preceded the revision.","Editing therefore involves more than selecting an elegant participle.","It tests the subject, the time relation, and any premise compressed into the clause.","These checks prevent concise prose from quietly strengthening a conclusion."],"questions":[{"id":"en-c1-08-reading0","type":"choice","skill":"reading","prompt":"Feasibility nimaga bog‘liq?","answers":["stable attendance"],"explanation":"Essential premise.","hint":"Having reviewed … / Concerned about … / Assuming that …","options":["stable attendance","every cost being zero","no assumptions"]},{"id":"en-c1-08-reading1","type":"choice","skill":"reading","prompt":"Claim reviewed xatosi?","answers":["the implied subject cannot review evidence"],"explanation":"Ega claim emas team.","hint":"Having reviewed … / Concerned about … / Assuming that …","options":["the implied subject cannot review evidence","the review happened later necessarily","all passive is wrong"]},{"id":"en-c1-08-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Having reviewed … / Concerned about … / Assuming that …","options":["A proposal says, “Assuming that attendance remains stable, the plan is feasible.","” The assumption is essential: if attendance falls, the cost per participant may rise.","A shortened clause makes that condition compact, but readers must not lose it when quoting the recommendation.","Another sentence says, “Having reviewed the evidence, the claim was revised.","” Its implied subject is the claim, which cannot review evidence.","The writer names the team and checks whether the review actually preceded the revision.","Editing therefore involves more than selecting an elegant participle.","It tests the subject, the time relation, and any premise compressed into the clause.","These checks prevent concise prose from quietly strengthening a conclusion."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is premise. A proposal says, “Assuming that attendance remains stable, the plan is feasible. ” The assumption is essential: if attendance falls, the cost per participant may rise. Speaker two: My main point is qualification. Keep the assumption visible when quoting the recommendation. A proposal says, “Assuming that attendance remains stable, the plan is feasible.” The assumption is essential: if attendance falls, the cost per participant may rise. A shortened clause makes that condition compact, but readers must not lose it when quoting the recommendation. Another sentence says, “Having reviewed the evidence, the claim was revised.” Its implied subject is the claim, which cannot review evidence. The writer names the team and checks whether the review actually preceded the revision. Editing therefore involves more than selecting an elegant participle. It tests the subject, the time relation, and any premise compressed into the clause. These checks prevent concise prose from quietly strengthening a conclusion.","audio":"/english-course/v7.23/en-c1-08.mp3","synthetic":true,"questions":[{"id":"en-c1-08-listening0","type":"choice","skill":"listening","prompt":"Feasibility nimaga bog‘liq?","answers":["stable attendance"],"explanation":"Essential premise.","hint":"Having reviewed … / Concerned about … / Assuming that …","options":["stable attendance","every cost being zero","no assumptions"]},{"id":"en-c1-08-listening1","type":"choice","skill":"listening","prompt":"Claim reviewed xatosi?","answers":["the implied subject cannot review evidence"],"explanation":"Ega claim emas team.","hint":"Having reviewed … / Concerned about … / Assuming that …","options":["the implied subject cannot review evidence","the review happened later necessarily","all passive is wrong"]},{"id":"en-c1-08-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["premise","qualification"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Having reviewed … / Concerned about … / Assuming that …","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-08-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Written for specialists, the report needs explanation."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Having reviewed … / Concerned about … / Assuming that …","audio":"/english-course/v7.23/en-c1-08-dictation.mp3","transcript":"Written for specialists, the report needs explanation."}]},"writing":{"task":"Proposalni uch participle clause bilan yozib, yashirin premise va egani tekshiring.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Having reviewed the attendance figures, the team considers the plan feasible. This conclusion assumes that participation remains broadly stable; a substantial fall would change the cost per participant. Written for the committee, the report should make that premise visible rather than bury it in a compact clause. Not having compared alternative schedules, we cannot claim that this arrangement is the most efficient. We can recommend a limited trial while keeping the conditions of that recommendation explicit.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["Having reviewed the evidence, we revised the claim.","Concerned about access, the committee requested a trial.","Assuming that attendance remains stable, the plan is feasible."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Proposalni uch participle clause bilan yozib, yashirin premise va egani tekshiring. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Proposalni uch participle clause bilan yozib, yashirin premise va egani tekshiring.","exit":[[{"id":"en-c1-08-exit0","type":"grammarFill","skill":"grammar","prompt":"Having ___ the evidence, we revised it. (review)","answers":["reviewed"],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …"},{"id":"en-c1-08-exit1","type":"grammarFill","skill":"grammar","prompt":"___ for specialists, the report needs explanation. (write)","answers":["Written"],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …"},{"id":"en-c1-08-exit2","type":"grammarFill","skill":"grammar","prompt":"Not ___ compared groups, we cannot identify cause.","answers":["having"],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …"},{"id":"en-c1-08-exit3","type":"choice","skill":"grammar","prompt":"Feasibility nimaga bog‘liq?","answers":["stable attendance"],"explanation":"Essential premise.","hint":"Having reviewed … / Concerned about … / Assuming that …","options":["stable attendance","every cost being zero","no assumptions"]},{"id":"en-c1-08-exit4","type":"choice","skill":"grammar","prompt":"Claim reviewed xatosi?","answers":["the implied subject cannot review evidence"],"explanation":"Ega claim emas team.","hint":"Having reviewed … / Concerned about … / Assuming that …","options":["the implied subject cannot review evidence","the review happened later necessarily","all passive is wrong"]}],[{"id":"en-c1-08-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Concerned about access, the committee requested a trial."],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …","tokens":["Concerned","about","access,","the","committee","requested","a","trial."]},{"id":"en-c1-08-exit-b1","type":"grammarFill","skill":"grammar","prompt":"___ for specialists, the report needs explanation. (write)","answers":["Written"],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …"},{"id":"en-c1-08-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Written for specialists, the report needs explanation."],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …","tokens":["Written","for","specialists,","the","report","needs","explanation."]},{"id":"en-c1-08-exit-b3","type":"choice","skill":"grammar","prompt":"Feasibility nimaga bog‘liq?","answers":["stable attendance"],"explanation":"Essential premise.","hint":"Having reviewed … / Concerned about … / Assuming that …","options":["stable attendance","every cost being zero","no assumptions"]},{"id":"en-c1-08-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Working with limited data, the team stated its uncertainty."],"explanation":"Having + V3 oldin tugagan amal; -ing bir vaqtdagi yoki sababiy aloqa bo‘lishi mumkin. Ega asosiy gap bilan mos; passive uchun past participle. Participle sababni taxminan berishi mumkin; as/because bilan kengaytirib dalilni tekshiring.","hint":"Having reviewed … / Concerned about … / Assuming that …","tokens":["Working","with","limited","data,","the","team","stated","its","uncertainty."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-c1-08-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Conditional inversion va ehtiyot chorasi: Til vositasini tanlang: ___ we known, we would have revised it.","answers":["Had"],"explanation":"Had we known = if we had known; were it not for = if it were not for. Should you need … kelajak ehtimoli uchun rasmiy shart. Inverted clause yordamchini oldinga oladi, not egadan keyin; vaqt ma’nosi saqlansin.","hint":"Had we known / Were it not for / Should you need","options":["Had","Have","Were"],"recap":true,"sourceLesson":"Conditional inversion va ehtiyot chorasi"},{"id":"en-c1-08-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Hedging va epistemic modality: Til vositasini tanlang: The findings may ___ a trend. (suggest)","answers":["suggest"],"explanation":"May suggest, appears consistent with, is likely to turli ehtimol va dalil aloqalarini bildiradi. Must xulosa kuchi; must majburiyat ham bo‘lishi mumkin — kontekstni tekshiring. Hedging noaniqlikni yashirmasin: aynan nima noma’lum va nima aniq ekanini ayting.","hint":"may suggest / appears consistent with / cannot establish","options":["suggest","suggests","suggested"],"recap":true,"sourceLesson":"Hedging va epistemic modality"},{"id":"en-c1-08-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Murakkab reporting va passive: Til vositasini tanlang: The policy is believed to have been ___. (revise)","answers":["revised"],"explanation":"Is believed to have been changed oldingi passive hodisaga ishora qiladi. It has been suggested that … taklif, established fact emas. Bir manbani ko‘p sayt takrorlashi mustaqil tasdiq bo‘lmaydi.","hint":"is believed to have been / has been suggested that","options":["revised","revising","revise"],"recap":true,"sourceLesson":"Murakkab reporting va passive"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-09','en-c1-09',null,5,9,'published',1,'{"id":"en-c1-09","baseId":"en-c1-09","revision":1,"level":"C1","levelIndex":5,"order":9,"title":"Nominalisation: jarayon va bajaruvchi","objective":"Otlashtirishni aniqlik uchun ishlatasiz va yashirilgan agentni qayta ochasiz.","context":"Nominalisation: jarayon va bajaruvchi","prerequisites":["en-c1-08"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Implement → implementation; decide → decision jarayonni noun qiladi.","Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin.","It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq."],"pattern":"implementation / evaluation / allocation","examples":["The committee implemented the plan.","Implementation began in May.","The allocation of rooms was reviewed.","The review identified a communication gap.","The organiser allocated two rooms.","Evaluation should include access as well as cost."],"vocabulary":[{"id":"en-c1-09-v0","term":"implementation","meaning":"amalga oshirish","ipa":"/ˌɪmplɪmenˈteɪʃən/","collocation":"monitor implementation","example":"Implementation began in May."},{"id":"en-c1-09-v1","term":"allocation","meaning":"taqsimlash","ipa":"/ˌæləˈkeɪʃən/","collocation":"room allocation","example":"The allocation of rooms was reviewed."},{"id":"en-c1-09-v2","term":"evaluation","meaning":"baholash","ipa":"/ɪˌvæljuˈeɪʃən/","collocation":"an independent evaluation","example":"Evaluation should include access as well as cost."},{"id":"en-c1-09-v3","term":"accountability","meaning":"hisobdorlik","ipa":"/əˌkaʊntəˈbɪləti/","collocation":"maintain accountability","example":"maintain accountability"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["implementation / evaluation / allocation","The committee implemented the plan.","Implementation began in May."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["An abstract noun hides the agent.","The expanded sentence names the organiser and sequence.","Use nominalisation after the action becomes clear."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The review identified a communication gap.","audio":"/english-course/v7.23/en-c1-09-dictation.mp3"},"exercises":[{"id":"en-c1-09-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Implement → noun: ___","answers":["implementation"],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation","options":["implementation","implement","implements"]},{"id":"en-c1-09-gap","type":"grammarFill","skill":"grammar","prompt":"Implement → noun: ___","answers":["implementation"],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation"},{"id":"en-c1-09-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The committee implemented the plan."],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation","tokens":["The","committee","implemented","the","plan."]},{"id":"en-c1-09-fix","type":"correction","skill":"grammar","prompt":"The exclusion proves the organiser intended harm.","answers":["The allocation excluded a group, but does not establish the organiser’s intention."],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation"},{"id":"en-c1-09-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["amalga oshirish","taqsimlash","baholash","hisobdorlik"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"implementation / evaluation / allocation","left":["implementation","allocation","evaluation","accountability"],"options":["amalga oshirish","taqsimlash","baholash","hisobdorlik"]},{"id":"en-c1-09-transform","type":"transformation","skill":"grammar","prompt":"Agentni oching: Room allocation was carried out by the organiser.","answers":["The organiser allocated the rooms."],"hint":"implementation / evaluation / allocation","explanation":"Implement → implementation; decide → decision jarayonni noun qiladi."},{"id":"en-c1-09-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["An abstract noun hides the agent.","The expanded sentence names the organiser and sequence.","Use nominalisation after the action becomes clear."],"answers":["An abstract noun hides the agent.\nThe expanded sentence names the organiser and sequence.\nUse nominalisation after the action becomes clear."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-09-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["implementation","allocation","evaluation","accountability"],"options":["monitor implementation","room allocation","an independent evaluation","maintain accountability"],"answers":["monitor implementation","room allocation","an independent evaluation","maintain accountability"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The report states that the allocation of rooms resulted in the exclusion of one group. Readers can identify the outcome but not who allocated the rooms or whether the exclusion was intended. The writer expands the sentence: the organiser assigned both rooms to early applicants, leaving later applicants without space. This version names the agent and explains the sequence without guessing intent. Later, the report uses “the allocation” to refer back to that process efficiently. Nominalisation is therefore not inherently evasive. It can maintain cohesion once the action is clear. Problems arise when abstract nouns replace necessary information about who acted, when, and under which criteria. A good revision alternates explicit actions with concise references to them.","sentences":["The report states that the allocation of rooms resulted in the exclusion of one group.","Readers can identify the outcome but not who allocated the rooms or whether the exclusion was intended.","The writer expands the sentence: the organiser assigned both rooms to early applicants, leaving later applicants without space.","This version names the agent and explains the sequence without guessing intent.","Later, the report uses “the allocation” to refer back to that process efficiently.","Nominalisation is therefore not inherently evasive.","It can maintain cohesion once the action is clear.","Problems arise when abstract nouns replace necessary information about who acted, when, and under which criteria.","A good revision alternates explicit actions with concise references to them."],"questions":[{"id":"en-c1-09-reading0","type":"choice","skill":"reading","prompt":"Expanded sentence nimani qo‘shdi?","answers":["agent and sequence"],"explanation":"Kim taqsimlagani va tartib.","hint":"implementation / evaluation / allocation","options":["agent and sequence","proof of intent","a new outcome"]},{"id":"en-c1-09-reading1","type":"choice","skill":"reading","prompt":"Nominalisation har doim evasivmi?","answers":["No, it can link known actions"],"explanation":"Ma’lum jarayonga ixcham qaytish.","hint":"implementation / evaluation / allocation","options":["No, it can link known actions","Yes, always","only in short words"]},{"id":"en-c1-09-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"implementation / evaluation / allocation","options":["The report states that the allocation of rooms resulted in the exclusion of one group.","Readers can identify the outcome but not who allocated the rooms or whether the exclusion was intended.","The writer expands the sentence: the organiser assigned both rooms to early applicants, leaving later applicants without space.","This version names the agent and explains the sequence without guessing intent.","Later, the report uses “the allocation” to refer back to that process efficiently.","Nominalisation is therefore not inherently evasive.","It can maintain cohesion once the action is clear.","Problems arise when abstract nouns replace necessary information about who acted, when, and under which criteria.","A good revision alternates explicit actions with concise references to them."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is allocation. The report states that the allocation of rooms resulted in the exclusion of one group. Readers can identify the outcome but not who allocated the rooms or whether the exclusion was intended. Speaker two: My main point is accountability. Name the action before using an abstract noun to refer back to it. The report states that the allocation of rooms resulted in the exclusion of one group. Readers can identify the outcome but not who allocated the rooms or whether the exclusion was intended. The writer expands the sentence: the organiser assigned both rooms to early applicants, leaving later applicants without space. This version names the agent and explains the sequence without guessing intent. Later, the report uses “the allocation” to refer back to that process efficiently. Nominalisation is therefore not inherently evasive. It can maintain cohesion once the action is clear. Problems arise when abstract nouns replace necessary information about who acted, when, and under which criteria. A good revision alternates explicit actions with concise references to them.","audio":"/english-course/v7.23/en-c1-09.mp3","synthetic":true,"questions":[{"id":"en-c1-09-listening0","type":"choice","skill":"listening","prompt":"Expanded sentence nimani qo‘shdi?","answers":["agent and sequence"],"explanation":"Kim taqsimlagani va tartib.","hint":"implementation / evaluation / allocation","options":["agent and sequence","proof of intent","a new outcome"]},{"id":"en-c1-09-listening1","type":"choice","skill":"listening","prompt":"Nominalisation har doim evasivmi?","answers":["No, it can link known actions"],"explanation":"Ma’lum jarayonga ixcham qaytish.","hint":"implementation / evaluation / allocation","options":["No, it can link known actions","Yes, always","only in short words"]},{"id":"en-c1-09-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["allocation","accountability"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"implementation / evaluation / allocation","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-09-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The review identified a communication gap."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"implementation / evaluation / allocation","audio":"/english-course/v7.23/en-c1-09-dictation.mp3","transcript":"The review identified a communication gap."}]},"writing":{"task":"Bitta abstract reportni agentli gaplarga oching, keyin cohesion uchun otlashtiring.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The organiser allocated both rooms to early applicants, leaving later groups without space. This allocation followed the order of application, but the report does not show whether the criteria had been announced clearly. Evaluation should therefore examine communication as well as the outcome. Using the noun “allocation” helps refer back to the process once the agent and sequence are explicit. It should not replace the information readers need to understand responsibility or imply an intention the evidence does not establish.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The committee implemented the plan.","Implementation began in May.","The allocation of rooms was reviewed."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Bitta abstract reportni agentli gaplarga oching, keyin cohesion uchun otlashtiring. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Bitta abstract reportni agentli gaplarga oching, keyin cohesion uchun otlashtiring.","exit":[[{"id":"en-c1-09-exit0","type":"grammarFill","skill":"grammar","prompt":"Implement → noun: ___","answers":["implementation"],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation"},{"id":"en-c1-09-exit1","type":"grammarFill","skill":"grammar","prompt":"Evaluate → noun: ___","answers":["evaluation"],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation"},{"id":"en-c1-09-exit2","type":"grammarFill","skill":"grammar","prompt":"Allocate → noun: ___","answers":["allocation"],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation"},{"id":"en-c1-09-exit3","type":"choice","skill":"grammar","prompt":"Expanded sentence nimani qo‘shdi?","answers":["agent and sequence"],"explanation":"Kim taqsimlagani va tartib.","hint":"implementation / evaluation / allocation","options":["agent and sequence","proof of intent","a new outcome"]},{"id":"en-c1-09-exit4","type":"choice","skill":"grammar","prompt":"Nominalisation har doim evasivmi?","answers":["No, it can link known actions"],"explanation":"Ma’lum jarayonga ixcham qaytish.","hint":"implementation / evaluation / allocation","options":["No, it can link known actions","Yes, always","only in short words"]}],[{"id":"en-c1-09-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Implementation began in May."],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation","tokens":["Implementation","began","in","May."]},{"id":"en-c1-09-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Evaluate → noun: ___","answers":["evaluation"],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation"},{"id":"en-c1-09-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The review identified a communication gap."],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation","tokens":["The","review","identified","a","communication","gap."]},{"id":"en-c1-09-exit-b3","type":"choice","skill":"grammar","prompt":"Expanded sentence nimani qo‘shdi?","answers":["agent and sequence"],"explanation":"Kim taqsimlagani va tartib.","hint":"implementation / evaluation / allocation","options":["agent and sequence","proof of intent","a new outcome"]},{"id":"en-c1-09-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Evaluation should include access as well as cost."],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation","tokens":["Evaluation","should","include","access","as","well","as","cost."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-10','en-c1-10',null,5,10,'published',1,'{"id":"en-c1-10","baseId":"en-c1-10","revision":1,"level":"C1","levelIndex":5,"order":10,"title":"Ellipsis va substitution","objective":"Takrorni kamaytirib, yashirin ma’no manbasini aniq saqlaysiz.","context":"Ellipsis va substitution","prerequisites":["en-c1-09"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["So/neither yordamchi bilan: So do I; neither did she.","Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin.","Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang."],"pattern":"do so / one / I think so / neither did","examples":["We tested the first plan, and they did so too.","The cheaper option is not always the better one.","Will the trial continue? I think so.","I did not agree, and neither did she.","Some preferred mornings; others, afternoons.","The team could revise the plan, but chose not to."],"vocabulary":[{"id":"en-c1-10-v0","term":"referent","meaning":"ishora qilingan birlik","ipa":"/ˈrefərənt/","collocation":"a clear referent","example":"a clear referent"},{"id":"en-c1-10-v1","term":"recover","meaning":"tiklamoq","ipa":"/rɪˈkʌvə/","collocation":"recover omitted meaning","example":"Ellipsis works when the omitted material can be recovered without changing the claim."},{"id":"en-c1-10-v2","term":"parallel","meaning":"parallel mos","ipa":"/ˈpærəlel/","collocation":"a parallel structure","example":"a parallel structure"},{"id":"en-c1-10-v3","term":"substitution","meaning":"almashtirish","ipa":"/ˌsʌbstɪˈtjuːʃən/","collocation":"use substitution","example":"The substitution hides a meaningful difference, so the editor restores the full verb."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["do so / one / I think so / neither did","We tested the first plan, and they did so too.","The cheaper option is not always the better one."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["One group tested; another discussed.","Substitution would imply the same activity.","Restore the verbs where the distinction matters."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"I did not agree, and neither did she.","audio":"/english-course/v7.23/en-c1-10-dictation.mp3"},"exercises":[{"id":"en-c1-10-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Did so substitution qolipini to‘ldiring: They tested it, and we did ___ too.","answers":["so"],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did","options":["so","either","neither"]},{"id":"en-c1-10-gap","type":"grammarFill","skill":"grammar","prompt":"Did so substitution qolipini to‘ldiring: They tested it, and we did ___ too.","answers":["so"],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did"},{"id":"en-c1-10-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We tested the first plan, and they did so too."],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did","tokens":["We","tested","the","first","plan,","and","they","did","so","too."]},{"id":"en-c1-10-fix","type":"correction","skill":"grammar","prompt":"We discussed it, and they tested it, so both groups did the same thing.","answers":["One group discussed it, while the other tested it."],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did"},{"id":"en-c1-10-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["ishora qilingan birlik","tiklamoq","parallel mos","almashtirish"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"do so / one / I think so / neither did","left":["referent","recover","parallel","substitution"],"options":["ishora qilingan birlik","tiklamoq","parallel mos","almashtirish"]},{"id":"en-c1-10-transform","type":"transformation","skill":"grammar","prompt":"Ellipsis: Some preferred mornings; others preferred afternoons.","answers":["Some preferred mornings; others, afternoons."],"hint":"do so / one / I think so / neither did","explanation":"So/neither yordamchi bilan: So do I; neither did she."},{"id":"en-c1-10-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["One group tested; another discussed.","Substitution would imply the same activity.","Restore the verbs where the distinction matters."],"answers":["One group tested; another discussed.\nSubstitution would imply the same activity.\nRestore the verbs where the distinction matters."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A summary says that one group tested the plan and another did so too. Readers naturally infer that the groups performed comparable tests. In fact, the second group only discussed the plan. The substitution hides a meaningful difference, so the editor restores the full verb. Elsewhere, “some preferred mornings; others, afternoons” is concise and accurate because the missing verb is shared. Ellipsis works when the omitted material can be recovered without changing the claim. The same principle applies to “the better one”: readers need to know which options are being compared and by which criterion. Advanced cohesion is not simply fewer repeated words. It is economical wording that preserves the distinctions necessary for fair interpretation.","sentences":["A summary says that one group tested the plan and another did so too.","Readers naturally infer that the groups performed comparable tests.","In fact, the second group only discussed the plan.","The substitution hides a meaningful difference, so the editor restores the full verb.","Elsewhere, “some preferred mornings; others, afternoons” is concise and accurate because the missing verb is shared.","Ellipsis works when the omitted material can be recovered without changing the claim.","The same principle applies to “the better one”: readers need to know which options are being compared and by which criterion.","Advanced cohesion is not simply fewer repeated words.","It is economical wording that preserves the distinctions necessary for fair interpretation."],"questions":[{"id":"en-c1-10-reading0","type":"choice","skill":"reading","prompt":"Did so nimani noto‘g‘ri anglatdi?","answers":["comparable testing"],"explanation":"Aslida second faqat muhokama.","hint":"do so / one / I think so / neither did","options":["comparable testing","different discussion only","no group acted"]},{"id":"en-c1-10-reading1","type":"choice","skill":"reading","prompt":"Qaysi ellipsis asoslangan?","answers":["some preferred mornings; others, afternoons"],"explanation":"Shared verb bir xil.","hint":"do so / one / I think so / neither did","options":["some preferred mornings; others, afternoons","tested and discussed are identical","every option is the better one"]},{"id":"en-c1-10-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"do so / one / I think so / neither did","options":["A summary says that one group tested the plan and another did so too.","Readers naturally infer that the groups performed comparable tests.","In fact, the second group only discussed the plan.","The substitution hides a meaningful difference, so the editor restores the full verb.","Elsewhere, “some preferred mornings; others, afternoons” is concise and accurate because the missing verb is shared.","Ellipsis works when the omitted material can be recovered without changing the claim.","The same principle applies to “the better one”: readers need to know which options are being compared and by which criterion.","Advanced cohesion is not simply fewer repeated words.","It is economical wording that preserves the distinctions necessary for fair interpretation."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is referent. A summary says that one group tested the plan and another did so too. Readers naturally infer that the groups performed comparable tests. Speaker two: My main point is distinction. Substitution must preserve the distinction between testing and discussing. A summary says that one group tested the plan and another did so too. Readers naturally infer that the groups performed comparable tests. In fact, the second group only discussed the plan. The substitution hides a meaningful difference, so the editor restores the full verb. Elsewhere, “some preferred mornings; others, afternoons” is concise and accurate because the missing verb is shared. Ellipsis works when the omitted material can be recovered without changing the claim. The same principle applies to “the better one”: readers need to know which options are being compared and by which criterion. Advanced cohesion is not simply fewer repeated words. It is economical wording that preserves the distinctions necessary for fair interpretation.","audio":"/english-course/v7.23/en-c1-10.mp3","synthetic":true,"questions":[{"id":"en-c1-10-listening0","type":"choice","skill":"listening","prompt":"Did so nimani noto‘g‘ri anglatdi?","answers":["comparable testing"],"explanation":"Aslida second faqat muhokama.","hint":"do so / one / I think so / neither did","options":["comparable testing","different discussion only","no group acted"]},{"id":"en-c1-10-listening1","type":"choice","skill":"listening","prompt":"Qaysi ellipsis asoslangan?","answers":["some preferred mornings; others, afternoons"],"explanation":"Shared verb bir xil.","hint":"do so / one / I think so / neither did","options":["some preferred mornings; others, afternoons","tested and discussed are identical","every option is the better one"]},{"id":"en-c1-10-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["referent","distinction"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"do so / one / I think so / neither did","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-10-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["I did not agree, and neither did she."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"do so / one / I think so / neither did","audio":"/english-course/v7.23/en-c1-10-dictation.mp3","transcript":"I did not agree, and neither did she."}]},"writing":{"task":"Summaryda substitution qo‘llang, har referent va omitted materialni izohlang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The first group tested the timetable, while the second discussed it. I have kept both verbs because “did so too” would imply comparable activity. Some participants preferred mornings; others, afternoons. Here the omitted verb is shared and easily recovered. The cheaper option may be useful, but it is not necessarily the better one for access. That final substitution remains clear only if the reader knows the options and the criterion. Concision should preserve meaningful distinctions rather than conceal them.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["We tested the first plan, and they did so too.","The cheaper option is not always the better one.","Will the trial continue? I think so."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Summaryda substitution qo‘llang, har referent va omitted materialni izohlang. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Summaryda substitution qo‘llang, har referent va omitted materialni izohlang.","exit":[[{"id":"en-c1-10-exit0","type":"grammarFill","skill":"grammar","prompt":"They tested it, and we did ___ too.","answers":["so"],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did"},{"id":"en-c1-10-exit1","type":"grammarFill","skill":"grammar","prompt":"I did not agree; neither ___ she.","answers":["did"],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did"},{"id":"en-c1-10-exit2","type":"grammarFill","skill":"grammar","prompt":"The better ___ is unclear. (option o‘rnida)","answers":["one"],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did"},{"id":"en-c1-10-exit3","type":"choice","skill":"grammar","prompt":"Did so nimani noto‘g‘ri anglatdi?","answers":["comparable testing"],"explanation":"Aslida second faqat muhokama.","hint":"do so / one / I think so / neither did","options":["comparable testing","different discussion only","no group acted"]},{"id":"en-c1-10-exit4","type":"choice","skill":"grammar","prompt":"Qaysi ellipsis asoslangan?","answers":["some preferred mornings; others, afternoons"],"explanation":"Shared verb bir xil.","hint":"do so / one / I think so / neither did","options":["some preferred mornings; others, afternoons","tested and discussed are identical","every option is the better one"]}],[{"id":"en-c1-10-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The cheaper option is not always the better one."],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did","tokens":["The","cheaper","option","is","not","always","the","better","one."]},{"id":"en-c1-10-exit-b1","type":"grammarFill","skill":"grammar","prompt":"I did not agree; neither ___ she.","answers":["did"],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did"},{"id":"en-c1-10-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I did not agree, and neither did she."],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did","tokens":["I","did","not","agree,","and","neither","did","she."]},{"id":"en-c1-10-exit-b3","type":"choice","skill":"grammar","prompt":"Did so nimani noto‘g‘ri anglatdi?","answers":["comparable testing"],"explanation":"Aslida second faqat muhokama.","hint":"do so / one / I think so / neither did","options":["comparable testing","different discussion only","no group acted"]},{"id":"en-c1-10-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The team could revise the plan, but chose not to."],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did","tokens":["The","team","could","revise","the","plan,","but","chose","not","to."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"ellipsis","name":"Cambridge English — Ellipsis (C1–C2)","levels":["C1"],"skill":"grammar","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1g060-ellipsis","task":"Tashlangan gap bo‘lagini tiklang va referentni tekshiring.","lesson":"en-c1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-11','en-c1-11',null,5,11,'published',1,'{"id":"en-c1-11","baseId":"en-c1-11","revision":1,"level":"C1","levelIndex":5,"order":11,"title":"Complex relative va noun clauses","objective":"What, whoever, whose va proposition clauses bilan aniq chegaralar berasiz.","context":"Complex relative va noun clauses","prerequisites":["en-c1-10"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["What = the thing that; the thing what standard shakl emas.","Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin.","That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi."],"pattern":"what matters / whether … / whoever … / which …","examples":["What matters is whether the plan improves access.","Whoever leads the trial must record attendance.","The group whose proposal was accepted will present.","The fact that attendance rose needs explanation.","They revised the plan, which reduced confusion.","We cannot assume that every participant benefited."],"vocabulary":[{"id":"en-c1-11-v0","term":"proposition","meaning":"ifodalangan da’vo","ipa":"/ˌprɒpəˈzɪʃən/","collocation":"evaluate a proposition","example":"evaluate a proposition"},{"id":"en-c1-11-v1","term":"scope","meaning":"qamrov","ipa":"/skəʊp/","collocation":"define the scope","example":"Clear clause relations define the scope of claims and help readers locate what still needs investigation."},{"id":"en-c1-11-v2","term":"antecedent","meaning":"oldingi tayanch birlik","ipa":"/ˌæntɪˈsiːdənt/","collocation":"a clear antecedent","example":"a clear antecedent"},{"id":"en-c1-11-v3","term":"beneficiary","meaning":"foyda oluvchi","ipa":"/ˌbenɪˈfɪʃəri/","collocation":"identify beneficiaries","example":"identify beneficiaries"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["what matters / whether … / whoever … / which …","What matters is whether the plan improves access.","Whoever leads the trial must record attendance."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The total rose.","The beneficiaries remain unidentified.","Investigate who gained access rather than infer from the total."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The fact that attendance rose needs explanation.","audio":"/english-course/v7.23/en-c1-11-dictation.mp3"},"exercises":[{"id":"en-c1-11-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: ___ matters is whether access improves.","answers":["What"],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …","options":["What","When","Where"]},{"id":"en-c1-11-gap","type":"grammarFill","skill":"grammar","prompt":"___ matters is whether access improves.","answers":["What"],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …"},{"id":"en-c1-11-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["What matters is whether the plan improves access."],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …","tokens":["What","matters","is","whether","the","plan","improves","access."]},{"id":"en-c1-11-fix","type":"correction","skill":"grammar","prompt":"The thing what matters is access.","answers":["What matters is access."],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …"},{"id":"en-c1-11-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["ifodalangan da’vo","qamrov","oldingi tayanch birlik","foyda oluvchi"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"what matters / whether … / whoever … / which …","left":["proposition","scope","antecedent","beneficiary"],"options":["ifodalangan da’vo","qamrov","oldingi tayanch birlik","foyda oluvchi"]},{"id":"en-c1-11-transform","type":"transformation","skill":"grammar","prompt":"Noun clause bilan: Did the plan help distant students? This is uncertain.","answers":["Whether the plan helped distant students is uncertain."],"hint":"what matters / whether … / whoever … / which …","explanation":"What = the thing that; the thing what standard shakl emas."},{"id":"en-c1-11-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The total rose.","The beneficiaries remain unidentified.","Investigate who gained access rather than infer from the total."],"answers":["The total rose.\nThe beneficiaries remain unidentified.\nInvestigate who gained access rather than infer from the total."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The committee agrees that what matters is whether the new schedule improves access. Attendance rose, but that fact alone does not show who benefited. The group whose proposal was accepted reports that more students came on the first day. Another group asks whether distant students attended more often or whether nearby students simply returned twice. Both interpretations fit the total. A noun clause lets the writer state the uncertainty rather than convert it into a conclusion. The summary also uses “which reduced confusion” to refer to the revision of the notice, not to the committee itself. Clear clause relations define the scope of claims and help readers locate what still needs investigation.","sentences":["The committee agrees that what matters is whether the new schedule improves access.","Attendance rose, but that fact alone does not show who benefited.","The group whose proposal was accepted reports that more students came on the first day.","Another group asks whether distant students attended more often or whether nearby students simply returned twice.","Both interpretations fit the total.","A noun clause lets the writer state the uncertainty rather than convert it into a conclusion.","The summary also uses “which reduced confusion” to refer to the revision of the notice, not to the committee itself.","Clear clause relations define the scope of claims and help readers locate what still needs investigation."],"questions":[{"id":"en-c1-11-reading0","type":"choice","skill":"reading","prompt":"Attendance total nimani ko‘rsatmaydi?","answers":["who benefited"],"explanation":"Kimlar o‘zgargani noma’lum.","hint":"what matters / whether … / whoever … / which …","options":["who benefited","that attendance rose","a reported total"]},{"id":"en-c1-11-reading1","type":"choice","skill":"reading","prompt":"Whether nima saqlaydi?","answers":["alternative interpretations"],"explanation":"Ikki talqin ochiq.","hint":"what matters / whether … / whoever … / which …","options":["alternative interpretations","a guaranteed benefit","a named leader only"]},{"id":"en-c1-11-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"what matters / whether … / whoever … / which …","options":["The committee agrees that what matters is whether the new schedule improves access.","Attendance rose, but that fact alone does not show who benefited.","The group whose proposal was accepted reports that more students came on the first day.","Another group asks whether distant students attended more often or whether nearby students simply returned twice.","Both interpretations fit the total.","A noun clause lets the writer state the uncertainty rather than convert it into a conclusion.","The summary also uses “which reduced confusion” to refer to the revision of the notice, not to the committee itself.","Clear clause relations define the scope of claims and help readers locate what still needs investigation."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is scope. The committee agrees that what matters is whether the new schedule improves access. Attendance rose, but that fact alone does not show who benefited. Speaker two: My main point is beneficiaries. A higher total does not identify the beneficiaries. The committee agrees that what matters is whether the new schedule improves access. Attendance rose, but that fact alone does not show who benefited. The group whose proposal was accepted reports that more students came on the first day. Another group asks whether distant students attended more often or whether nearby students simply returned twice. Both interpretations fit the total. A noun clause lets the writer state the uncertainty rather than convert it into a conclusion. The summary also uses “which reduced confusion” to refer to the revision of the notice, not to the committee itself. Clear clause relations define the scope of claims and help readers locate what still needs investigation.","audio":"/english-course/v7.23/en-c1-11.mp3","synthetic":true,"questions":[{"id":"en-c1-11-listening0","type":"choice","skill":"listening","prompt":"Attendance total nimani ko‘rsatmaydi?","answers":["who benefited"],"explanation":"Kimlar o‘zgargani noma’lum.","hint":"what matters / whether … / whoever … / which …","options":["who benefited","that attendance rose","a reported total"]},{"id":"en-c1-11-listening1","type":"choice","skill":"listening","prompt":"Whether nima saqlaydi?","answers":["alternative interpretations"],"explanation":"Ikki talqin ochiq.","hint":"what matters / whether … / whoever … / which …","options":["alternative interpretations","a guaranteed benefit","a named leader only"]},{"id":"en-c1-11-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["scope","beneficiaries"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"what matters / whether … / whoever … / which …","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-11-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The fact that attendance rose needs explanation."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"what matters / whether … / whoever … / which …","audio":"/english-course/v7.23/en-c1-11-dictation.mp3","transcript":"The fact that attendance rose needs explanation."}]},"writing":{"task":"Reportda what-matters clause, whether va whole-clause which bilan uncertainty aniqlang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"What matters is whether the schedule improves access for students who previously struggled to attend. The fact that total attendance rose is encouraging, but it does not identify the beneficiaries. The group whose proposal was accepted should compare participation by relevant groups rather than rely on the total alone. The notice was revised to clarify the schedule, which reduced confusion. That improvement is distinct from the unresolved question of access. Clear clause relations help keep those two findings separate.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["What matters is whether the plan improves access.","Whoever leads the trial must record attendance.","The group whose proposal was accepted will present."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Reportda what-matters clause, whether va whole-clause which bilan uncertainty aniqlang. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Reportda what-matters clause, whether va whole-clause which bilan uncertainty aniqlang.","exit":[[{"id":"en-c1-11-exit0","type":"grammarFill","skill":"grammar","prompt":"___ matters is whether access improves.","answers":["What"],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …"},{"id":"en-c1-11-exit1","type":"grammarFill","skill":"grammar","prompt":"The group ___ proposal was accepted will present.","answers":["whose"],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …"},{"id":"en-c1-11-exit2","type":"grammarFill","skill":"grammar","prompt":"We ask ___ distant students benefited.","answers":["whether"],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …"},{"id":"en-c1-11-exit3","type":"choice","skill":"grammar","prompt":"Attendance total nimani ko‘rsatmaydi?","answers":["who benefited"],"explanation":"Kimlar o‘zgargani noma’lum.","hint":"what matters / whether … / whoever … / which …","options":["who benefited","that attendance rose","a reported total"]},{"id":"en-c1-11-exit4","type":"choice","skill":"grammar","prompt":"Whether nima saqlaydi?","answers":["alternative interpretations"],"explanation":"Ikki talqin ochiq.","hint":"what matters / whether … / whoever … / which …","options":["alternative interpretations","a guaranteed benefit","a named leader only"]}],[{"id":"en-c1-11-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Whoever leads the trial must record attendance."],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …","tokens":["Whoever","leads","the","trial","must","record","attendance."]},{"id":"en-c1-11-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The group ___ proposal was accepted will present.","answers":["whose"],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …"},{"id":"en-c1-11-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The fact that attendance rose needs explanation."],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …","tokens":["The","fact","that","attendance","rose","needs","explanation."]},{"id":"en-c1-11-exit-b3","type":"choice","skill":"grammar","prompt":"Attendance total nimani ko‘rsatmaydi?","answers":["who benefited"],"explanation":"Kimlar o‘zgargani noma’lum.","hint":"what matters / whether … / whoever … / which …","options":["who benefited","that attendance rose","a reported total"]},{"id":"en-c1-11-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We cannot assume that every participant benefited."],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …","tokens":["We","cannot","assume","that","every","participant","benefited."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-12','en-c1-12',null,5,12,'published',1,'{"id":"en-c1-12","baseId":"en-c1-12","revision":1,"level":"C1","levelIndex":5,"order":12,"title":"Discourse markers va argument yo‘li","objective":"Indeed, nevertheless, conversely va consequentlyni real aloqa uchun tanlaysiz.","context":"Discourse markers va argument yo‘li","prerequisites":["en-c1-11"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat.","Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi.","Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring."],"pattern":"claim → nevertheless → qualification / consequently → result","examples":["The result is encouraging; nevertheless, the sample is limited.","The room was closed; consequently, the meeting moved.","Some prefer speed; conversely, others prioritise depth.","The survey is small; moreover, it excludes evening users.","Indeed, the interviews reveal a broader concern.","On balance, a further trial is justified."],"vocabulary":[{"id":"en-c1-12-v0","term":"concession","meaning":"qarshi hisobga olish","ipa":"/kənˈseʃən/","collocation":"signal concession","example":"signal concession"},{"id":"en-c1-12-v1","term":"consequence","meaning":"oqibat","ipa":"/ˈkɒnsɪkwəns/","collocation":"signal consequence","example":"These are not all causal consequences."},{"id":"en-c1-12-v2","term":"addition","meaning":"qo‘shimcha","ipa":"/əˈdɪʃən/","collocation":"a relevant addition","example":"a relevant addition"},{"id":"en-c1-12-v3","term":"inference","meaning":"anglangan xulosa","ipa":"/ˈɪnfərəns/","collocation":"a justified inference","example":"a justified inference"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["claim → nevertheless → qualification / consequently → result","The result is encouraging; nevertheless, the sample is limited.","The room was closed; consequently, the meeting moved."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Evidence and limitation coexist.","An additional group was excluded.","A further trial is a qualified judgement."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The survey is small; moreover, it excludes evening users.","audio":"/english-course/v7.23/en-c1-12-dictation.mp3"},"exercises":[{"id":"en-c1-12-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The result is good; ___, the sample is limited.","answers":["nevertheless"],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result","options":["nevertheless","because","although"]},{"id":"en-c1-12-gap","type":"grammarFill","skill":"grammar","prompt":"The result is good; ___, the sample is limited.","answers":["nevertheless"],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result"},{"id":"en-c1-12-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The result is encouraging; nevertheless, the sample is limited."],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result","tokens":["The","result","is","encouraging;","nevertheless,","the","sample","is","limited."]},{"id":"en-c1-12-fix","type":"correction","skill":"grammar","prompt":"The sample is limited; therefore, the positive result is certainly universal.","answers":["The result is positive; nevertheless, the sample is limited."],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result"},{"id":"en-c1-12-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["qarshi hisobga olish","oqibat","qo‘shimcha","anglangan xulosa"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"claim → nevertheless → qualification / consequently → result","left":["concession","consequence","addition","inference"],"options":["qarshi hisobga olish","oqibat","qo‘shimcha","anglangan xulosa"]},{"id":"en-c1-12-transform","type":"transformation","skill":"grammar","prompt":"Concession bilan: The result is encouraging, but the sample is limited.","answers":["The result is encouraging; nevertheless, the sample is limited."],"hint":"claim → nevertheless → qualification / consequently → result","explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat."},{"id":"en-c1-12-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Evidence and limitation coexist.","An additional group was excluded.","A further trial is a qualified judgement."],"answers":["Evidence and limitation coexist.\nAn additional group was excluded.\nA further trial is a qualified judgement."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-12-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["concession","consequence","addition","inference"],"options":["signal concession","signal consequence","a relevant addition","a justified inference"],"answers":["signal concession","signal consequence","a relevant addition","a justified inference"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."},{"id":"en-c1-12-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["The result is encouraging; nevertheless, the sample is limited."],"tokens":["The","result","is","encouraging;","nevertheless,","the","sample","is","limited."],"hint":"claim → nevertheless → qualification / consequently → result","explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat."},{"id":"en-c1-12-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Nominalisation: jarayon va bajaruvchi: Til vositasini tanlang: Implement → noun: ___","answers":["implementation"],"explanation":"Implement → implementation; decide → decision jarayonni noun qiladi. Nominalisation matnni ixcham bog‘laydi, ammo agent va vaqtni yashirishi mumkin. It led to the implementation of … o‘rniga kim nima qilganini yozish ba’zan aniqroq.","hint":"implementation / evaluation / allocation","options":["implementation","implement","implements"],"recap":true,"sourceLesson":"Nominalisation: jarayon va bajaruvchi"},{"id":"en-c1-12-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Ellipsis va substitution: Til vositasini tanlang: Did so substitution qolipini to‘ldiring: They tested it, and we did ___ too.","answers":["so"],"explanation":"So/neither yordamchi bilan: So do I; neither did she. Do so oldingi amal, one/ones ot, so/not clause mazmunini almashtirishi mumkin. Ellipsis kontekstdan tiklanadigan qismni tashlaydi; turli vazifalarni noto‘g‘ri tenglashtirmang.","hint":"do so / one / I think so / neither did","options":["so","either","neither"],"recap":true,"sourceLesson":"Ellipsis va substitution"},{"id":"en-c1-12-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Complex relative va noun clauses: Til vositasini tanlang: ___ matters is whether access improves.","answers":["What"],"explanation":"What = the thing that; the thing what standard shakl emas. Whoever shaxsni umumiy tanlaydi; whose egalikni, which oldingi clausega ishora qilishi mumkin. That-clause propositionni beradi; whether muqobil/noaniqlikni saqlaydi.","hint":"what matters / whether … / whoever … / which …","options":["What","When","Where"],"recap":true,"sourceLesson":"Complex relative va noun clauses"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A draft links every paragraph with “therefore.” It moves from a small survey to a recommendation, then from an access concern to a budget figure. These are not all causal consequences. The editor replaces one marker with “nevertheless” because the limitation qualifies an encouraging result. Another becomes “moreover” because the budget concern adds a different reason for caution. The recommendation remains the writer’s judgement, not an inevitable logical result. Readers need a transparent path through the argument. Discourse markers can reveal that path when chosen accurately, but they can also pretend that an unsupported jump is a deduction. The editor tests every connection by explaining it in ordinary language before selecting the marker.","sentences":["A draft links every paragraph with “therefore.","” It moves from a small survey to a recommendation, then from an access concern to a budget figure.","These are not all causal consequences.","The editor replaces one marker with “nevertheless” because the limitation qualifies an encouraging result.","Another becomes “moreover” because the budget concern adds a different reason for caution.","The recommendation remains the writer’s judgement, not an inevitable logical result.","Readers need a transparent path through the argument.","Discourse markers can reveal that path when chosen accurately, but they can also pretend that an unsupported jump is a deduction.","The editor tests every connection by explaining it in ordinary language before selecting the marker."],"questions":[{"id":"en-c1-12-reading0","type":"choice","skill":"reading","prompt":"Thereforelar muammosi?","answers":["not all connections were consequences"],"explanation":"Aloqalar turli.","hint":"claim → nevertheless → qualification / consequently → result","options":["not all connections were consequences","all paragraphs were identical","therefore is never valid"]},{"id":"en-c1-12-reading1","type":"choice","skill":"reading","prompt":"Recommendation qanday maqomda?","answers":["a reasoned judgement"],"explanation":"Dalilga tayangan baho, majburiy natija emas.","hint":"claim → nevertheless → qualification / consequently → result","options":["a reasoned judgement","an inevitable deduction","a survey response"]},{"id":"en-c1-12-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"claim → nevertheless → qualification / consequently → result","options":["A draft links every paragraph with “therefore.","” It moves from a small survey to a recommendation, then from an access concern to a budget figure.","These are not all causal consequences.","The editor replaces one marker with “nevertheless” because the limitation qualifies an encouraging result.","Another becomes “moreover” because the budget concern adds a different reason for caution.","The recommendation remains the writer’s judgement, not an inevitable logical result.","Readers need a transparent path through the argument.","Discourse markers can reveal that path when chosen accurately, but they can also pretend that an unsupported jump is a deduction.","The editor tests every connection by explaining it in ordinary language before selecting the marker."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is inference. A draft links every paragraph with “therefore. ” It moves from a small survey to a recommendation, then from an access concern to a budget figure. Speaker two: My main point is connection. Explain the connection before choosing its marker. A draft links every paragraph with “therefore.” It moves from a small survey to a recommendation, then from an access concern to a budget figure. These are not all causal consequences. The editor replaces one marker with “nevertheless” because the limitation qualifies an encouraging result. Another becomes “moreover” because the budget concern adds a different reason for caution. The recommendation remains the writer’s judgement, not an inevitable logical result. Readers need a transparent path through the argument. Discourse markers can reveal that path when chosen accurately, but they can also pretend that an unsupported jump is a deduction. The editor tests every connection by explaining it in ordinary language before selecting the marker.","audio":"/english-course/v7.23/en-c1-12.mp3","synthetic":true,"questions":[{"id":"en-c1-12-listening0","type":"choice","skill":"listening","prompt":"Thereforelar muammosi?","answers":["not all connections were consequences"],"explanation":"Aloqalar turli.","hint":"claim → nevertheless → qualification / consequently → result","options":["not all connections were consequences","all paragraphs were identical","therefore is never valid"]},{"id":"en-c1-12-listening1","type":"choice","skill":"listening","prompt":"Recommendation qanday maqomda?","answers":["a reasoned judgement"],"explanation":"Dalilga tayangan baho, majburiy natija emas.","hint":"claim → nevertheless → qualification / consequently → result","options":["a reasoned judgement","an inevitable deduction","a survey response"]},{"id":"en-c1-12-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["inference","connection"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"claim → nevertheless → qualification / consequently → result","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-12-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The survey is small; moreover, it excludes evening users."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"claim → nevertheless → qualification / consequently → result","audio":"/english-course/v7.23/en-c1-12-dictation.mp3","transcript":"The survey is small; moreover, it excludes evening users."}]},"writing":{"task":"Argument yo‘lini kamida to‘rt turdagi marker bilan tuzing va har aloqa vazifasini yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The survey result is encouraging; nevertheless, the small sample limits its scope. Moreover, evening users were excluded, so the findings do not represent every group. The interviews raise a separate access concern rather than a direct consequence of the survey. On balance, a further trial is justified, provided it collects broader evidence. This recommendation is a judgement about the available information. The markers should make the reasoning visible without presenting that judgement as an inevitable deduction.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The result is encouraging; nevertheless, the sample is limited.","The room was closed; consequently, the meeting moved.","Some prefer speed; conversely, others prioritise depth."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Argument yo‘lini kamida to‘rt turdagi marker bilan tuzing va har aloqa vazifasini yozing. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Argument yo‘lini kamida to‘rt turdagi marker bilan tuzing va har aloqa vazifasini yozing.","exit":[[{"id":"en-c1-12-exit0","type":"grammarFill","skill":"grammar","prompt":"The result is good; ___, the sample is limited.","answers":["nevertheless"],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result"},{"id":"en-c1-12-exit1","type":"grammarFill","skill":"grammar","prompt":"The room closed; ___, we moved.","answers":["consequently"],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result"},{"id":"en-c1-12-exit2","type":"grammarFill","skill":"grammar","prompt":"The sample is small; ___, it excludes evening users.","answers":["moreover"],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result"},{"id":"en-c1-12-exit3","type":"choice","skill":"grammar","prompt":"Thereforelar muammosi?","answers":["not all connections were consequences"],"explanation":"Aloqalar turli.","hint":"claim → nevertheless → qualification / consequently → result","options":["not all connections were consequences","all paragraphs were identical","therefore is never valid"]},{"id":"en-c1-12-exit4","type":"choice","skill":"grammar","prompt":"Recommendation qanday maqomda?","answers":["a reasoned judgement"],"explanation":"Dalilga tayangan baho, majburiy natija emas.","hint":"claim → nevertheless → qualification / consequently → result","options":["a reasoned judgement","an inevitable deduction","a survey response"]}],[{"id":"en-c1-12-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The room was closed; consequently, the meeting moved."],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result","tokens":["The","room","was","closed;","consequently,","the","meeting","moved."]},{"id":"en-c1-12-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The room closed; ___, we moved.","answers":["consequently"],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result"},{"id":"en-c1-12-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The survey is small; moreover, it excludes evening users."],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result","tokens":["The","survey","is","small;","moreover,","it","excludes","evening","users."]},{"id":"en-c1-12-exit-b3","type":"choice","skill":"grammar","prompt":"Thereforelar muammosi?","answers":["not all connections were consequences"],"explanation":"Aloqalar turli.","hint":"claim → nevertheless → qualification / consequently → result","options":["not all connections were consequences","all paragraphs were identical","therefore is never valid"]},{"id":"en-c1-12-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["On balance, a further trial is justified."],"explanation":"Nevertheless — kutilgan xulosaga qarshi; consequently — sababdan oqibat. Conversely teskari aloqa; moreover faqat yangi mos dalil qo‘shadi. Marker argument yaratmaydi: har aloqani markersiz oddiy gap bilan izohlab tekshiring.","hint":"claim → nevertheless → qualification / consequently → result","tokens":["On","balance,","a","further","trial","is","justified."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference